#include <iostream>
#include <vector>
using namespace std;

// 快速排序辅助函数：对区间 [l, r] 进行排序
void quick_sort(vector<int>& a, int l, int r) {
    if (l >= r) return;                      // 递归终止条件
    int p = a[l];                            // 基准值取第一个元素
    int i = l, j = r;
    while (i < j) {
        // 从右向左找到第一个小于基准的元素
        while (i < j && a[j] >= p) j--;
        // 从左向右找到第一个大于基准的元素
        while (i < j && a[i] <= p) i++;
        if (i < j) swap(a[i], a[j]);        // 交换逆序对
    }
    // 将基准放到正确位置（此时 i == j）
    swap(a[l], a[i]);
    // 递归处理左右子区间
    quick_sort(a, l, i - 1);
    quick_sort(a, i + 1, r);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<int> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];
    quick_sort(a, 0, n - 1);                 // 对整个数组排序
    for (int i = 0; i < n; i++) {
        if (i > 0) cout << ' ';
        cout << a[i];
    }
    return 0;
}

