int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int n, q;
    cin >> n >> q;
    vector<int> a(n);
    // 读入升序数组
    for (int i = 0; i < n; ++i) cin >> a[i];
    while (q--) {
        int x;
        cin >> x;
        // 二分查找左边界
        int l = 0, r = n - 1;
        while (l < r) {
            int mid = (l + r) / 2;
            if (a[mid] >= x) r = mid;
            else l = mid + 1;
        }
        // 若不存在，输出 -1 -1
        if (a[l] != x) {
            cout << "-1 -1\n";
            continue;
        }
        int L = l; // 记录左边界
        // 二分查找右边界
        l = 0, r = n - 1;
        while (l < r) {
            int mid = (l + r + 1) / 2;
            if (a[mid] <= x) l = mid;
            else r = mid - 1;
        }
        cout << L << " " << l << "\n";
    }
    return 0;
}

