#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    // 读入两个大整数（字符串形式）
    string s1, s2;
    cin >> s1 >> s2;

    // 将字符串反转，并转换为数字数组（低位在前）
    vector<int> a, b;
    for (int i = s1.size() - 1; i >= 0; --i)
        a.push_back(s1[i] - '0');
    for (int i = s2.size() - 1; i >= 0; --i)
        b.push_back(s2[i] - '0');

    // 逐位相加，处理进位
    int carry = 0;
    vector<int> res;
    int len = max(a.size(), b.size());
    for (int i = 0; i < len; ++i) {
        int digit = carry;
        if (i < a.size()) digit += a[i];
        if (i < b.size()) digit += b[i];
        res.push_back(digit % 10);
        carry = digit / 10;
    }
    // 若最后有进位，添加到最高位
    if (carry) res.push_back(carry);

    // 逆序输出结果（高位在前）
    for (int i = res.size() - 1; i >= 0; --i)
        cout << res[i];
    cout << endl;

    return 0;
}

