    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, q;
    cin >> n >> m >> q;

    // 创建 (n+1) x (m+1) 的前缀和数组，初始为0
    vector<vector<long long>> s(n + 1, vector<long long>(m + 1, 0));

    // 读入矩阵并计算前缀和
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= m; ++j) {
            int x;
            cin >> x;
            // 二维前缀和公式：s[i][j] = s[i-1][j] + s[i][j-1] - s[i-1][j-1] + a[i][j]
            s[i][j] = s[i-1][j] + s[i][j-1] - s[i-1][j-1] + x;
        }
    }

    // 处理每个查询
    while (q--) {
        int x1, y1, x2, y2;
        cin >> x1 >> y1 >> x2 >> y2;
        // 子矩阵和公式：sum = s[x2][y2] - s[x1-1][y2] - s[x2][y1-1] + s[x1-1][y1-1]
        long long ans = s[x2][y2] - s[x1-1][y2] - s[x2][y1-1] + s[x1-1][y1-1];
        cout << ans << '\n';
    }

    return 0;
}

