#include <iostream>
#include <unordered_map>
#include <algorithm>
#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n;
    cin >> n;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) cin >> a[i];

    // 哈希表记录每个数字当前窗口中出现的次数
    unordered_map<int, int> cnt;
    int res = 0;
    int j = 0; // 滑动窗口左指针

    for (int i = 0; i < n; ++i) { // 右指针 i 遍历序列
        cnt[a[i]]++; // 将当前数字加入窗口
        // 如果当前数字出现次数大于1，则窗口内出现重复，需要移动左指针
        while (cnt[a[i]] > 1) {
            cnt[a[j]]--; // 左指针指向的数字移出窗口
            j++;         // 左指针右移
        }
        // 更新最长不重复子序列的长度
        res = max(res, i - j + 1);
    }

    cout << res << endl;
    return 0;
}

