#include <iostream>
#include <vector>
#include <algorithm>
#include <set>
using namespace std;

typedef long long LL;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(NULL);

    int n, m;
    cin >> n >> m;

    vector<pair<int, int>> add;          // 存储 n 次加法操作 (位置, 值)
    vector<pair<int, int>> query;        // 存储 m 次询问 (左端点, 右端点)
    set<int> idxs;                       // 用集合收集所有出现过的坐标，自动去重排序

    // 读取 n 次加法
    for (int i = 0; i < n; ++i) {
        int x, c;
        cin >> x >> c;
        add.push_back({x, c});
        idxs.insert(x);
    }

    // 读取 m 次询问
    for (int i = 0; i < m; ++i) {
        int l, r;
        cin >> l >> r;
        query.push_back({l, r});
        idxs.insert(l);
        idxs.insert(r);
    }

    // 将集合转为有序向量，便于二分查找
    vector<int> idxsVec(idxs.begin(), idxs.end());

    // 定义离散化查找函数：给定原始坐标，返回 1-based 索引
    auto findIdx = [&](int x) -> int {
        return lower_bound(idxsVec.begin(), idxsVec.end(), x) - idxsVec.begin() + 1;
    };

    // 初始化差分数组（大小比坐标数多 2 以确保安全）
    vector<LL> diff(idxsVec.size() + 2, 0);

    // 执行所有加法操作，将值加到对应离散化位置
    for (auto &p : add) {
        int pos = findIdx(p.first);
        diff[pos] += p.second;
    }

    // 前缀和：将差分数组转换成前缀和数组
    for (size_t i = 1; i < diff.size(); ++i) {
        diff[i] += diff[i - 1];
    }

    // 处理每个询问，输出区间和
    for (auto &q : query) {
        int l = findIdx(q.first) - 1;   // 左端点前一个位置（注意减 1）
        int r = findIdx(q.second);      // 右端点位置
        cout << diff[r] - diff[l] << '\n';
    }

    return 0;
}

