#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    int n;
    cin >> n;
    vector<pair<int, int>> intervals(n);
    // 读入所有区间
    for (int i = 0; i < n; ++i) {
        cin >> intervals[i].first >> intervals[i].second;
    }
    // 按左端点升序排序
    sort(intervals.begin(), intervals.end());
    // 初始化：第一个区间作为当前合并区间
    int cnt = 1;                 // 合并后区间个数至少为1
    int curR = intervals[0].second;  // 当前合并区间的右端点
    // 从第二个区间开始遍历
    for (int i = 1; i < n; ++i) {
        int l = intervals[i].first;
        int r = intervals[i].second;
        if (l <= curR) {
            // 有重叠：更新当前右端点为两者较大值
            curR = max(curR, r);
        } else {
            // 无重叠：新区间开始，计数加一，重置右端点
            ++cnt;
            curR = r;
        }
    }
    cout << cnt << endl;
    return 0;
}

