#include <iostream>
#include <vector>
using namespace std;

const int N = 100010;

int e[N];      // 存储节点值
int ne[N];     // 存储下一节点指针（下标）
int head = -1; // 头节点指针，初始为空
int idx = 0;   // 当前可用节点下标

int main() {
    int m;
    cin >> m;

    while (m--) {
        char op;
        cin >> op;
        if (op == 'H') {          // 在头部插入 x
            int x;
            cin >> x;
            e[idx] = x;
            ne[idx] = head;
            head = idx;
            idx++;
        } else if (op == 'D') {    // 删除第 k 个插入节点后的节点（k=0 删除头节点）
            int k;
            cin >> k;
            if (k == 0) {
                head = ne[head];   // 删除头节点
            } else {
                ne[k - 1] = ne[ne[k - 1]]; // 删除第 k 个节点后面的节点
            }
        } else if (op == 'I') {    // 在第 k 个插入节点后插入 x
            int k, x;
            cin >> k >> x;
            e[idx] = x;
            ne[idx] = ne[k - 1];   // 新节点指向原第 k 个节点的后继
            ne[k - 1] = idx;       // 第 k 个节点指向新节点
            idx++;
        }
    }

    // 遍历链表输出
    vector<int> res;
    for (int cur = head; cur != -1; cur = ne[cur]) {
        res.push_back(e[cur]);
    }
    for (int i = 0; i < res.size(); i++) {
        if (i > 0) cout << ' ';
        cout << res[i];
    }
    cout << endl;

    return 0;
}

