#include <iostream>
#include <stack>
#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false); // 加速输入输出
    cin.tie(0);

    int n;
    cin >> n;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    stack<int> st;          // 单调递增栈，存储数值
    vector<int> res;        // 存储结果

    for (int x : a) {
        // 弹出栈中所有 >= x 的元素（因为它们不可能成为后续元素的“左边第一个小值”)
        while (!st.empty() && st.top() >= x) {
            st.pop();
        }
        // 栈顶元素即为左边第一个比 x 小的数，若栈空则为 -1
        res.push_back(st.empty() ? -1 : st.top());
        st.push(x);          // 将 x 入栈
    }

    // 输出结果，用空格分隔
    for (size_t i = 0; i < res.size(); ++i) {
        if (i > 0) cout << ' ';
        cout << res[i];
    }
    cout << endl;

    return 0;
}

