#include <iostream>
#include <string>
#include <vector>
using namespace std;

int main() {
    string t, p;
    cin >> t >> p;
    int n = t.size(), m = p.size();
    // 模式串为空，返回0
    if (m == 0) {
        cout << 0 << endl;
        return 0;
    }
    // 构建next数组（前缀函数）
    vector<int> nxt(m, 0);
    int j = 0;
    for (int i = 1; i < m; ++i) {
        // 当前字符不匹配，回退到上一个最长公共前后缀
        while (j > 0 && p[i] != p[j])
            j = nxt[j - 1];
        // 匹配成功，前缀长度+1
        if (p[i] == p[j])
            ++j;
        nxt[i] = j;
    }
    // 匹配过程
    j = 0;
    for (int i = 0; i < n; ++i) {
        // 当前字符不匹配，回退
        while (j > 0 && t[i] != p[j])
            j = nxt[j - 1];
        if (t[i] == p[j])
            ++j;
        // 完全匹配，输出起始位置
        if (j == m) {
            cout << i - m + 1 << endl;
            return 0;
        }
    }
    // 匹配失败
    cout << -1 << endl;
    return 0;
}

