const int N = 100010; // Trie树节点总数，根据题目数据范围设定

int son[N][26];  // 存储每个节点的子节点索引（0表示不存在）
int cnt[N];      // 存储以当前节点结尾的字符串出现次数
int idx;         // 当前已分配的节点编号，根节点为0

int main() {
    int n;
    cin >> n;

    string op, s;
    while (n--) {
        cin >> op >> s;

        if (op == "I") {
            // 插入操作
            int p = 0; // 从根节点开始
            for (char ch : s) {
                int c = ch - 'a'; // 将字符转换为0~25的索引
                if (!son[p][c]) {
                    // 如果当前节点的该子节点不存在，则创建新节点
                    son[p][c] = ++idx;
                }
                p = son[p][c]; // 移动到子节点
            }
            cnt[p]++; // 在字符串末尾标记出现次数+1
        } else {
            // 查询操作
            int p = 0;
            bool found = true;
            for (char ch : s) {
                int c = ch - 'a';
                if (!son[p][c]) {
                    // 路径中断，说明字符串不存在
                    found = false;
                    break;
                }
                p = son[p][c];
            }
            if (found) {
                cout << cnt[p] << endl; // 输出出现次数
            } else {
                cout << 0 << endl;
            }
        }
    }

    return 0;
}

