#include <iostream>
#include <cstring>
using namespace std;

const int N = 100003; // 哈希表大小，取质数
const int M = 100010; // 操作总数

int h[N];   // 哈希表头指针数组，初始化为-1表示空
int e[M], ne[M], idx; // 邻接表：e存储值，ne存储下一个节点下标，idx当前可用节点

// 插入操作
void insert(int x) {
    int k = (x % N + N) % N; // 计算哈希值，处理负数
    e[idx] = x;          // 存储值
    ne[idx] = h[k];      // 将新节点插入链表头部
    h[k] = idx++;        // 更新头指针
}

// 查找操作
bool find(int x) {
    int k = (x % N + N) % N; // 计算哈希值
    for (int i = h[k]; i != -1; i = ne[i]) { // 遍历链表
        if (e[i] == x)
            return true;
    }
    return false;
}

int main() {
    int n;
    cin >> n;

    memset(h, -1, sizeof h); // 初始化头指针为-1
    idx = 0;

    while (n--) {
        char op;
        int x;
        cin >> op >> x;
        if (op == 'I') {
            insert(x);
        } else { // op == 'Q'
            if (find(x))
                cout << "YES" << endl;
            else
                cout << "NO" << endl;
        }
    }

    return 0;
}

