#include <iostream>
#include <queue>
#include <vector>
using namespace std;

int main() {
    int n, m;
    cin >> n >> m;
    // 读入网格，0 可走，1 障碍
    vector<vector<int>> grid(n, vector<int>(m));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            cin >> grid[i][j];
        }
    }

    // 起点或终点本身就是障碍，直接输出 -1
    if (grid[0][0] == 1 || grid[n-1][m-1] == 1) {
        cout << -1 << endl;
        return 0;
    }

    // BFS 队列，存储坐标
    queue<pair<int, int>> q;
    q.push({0, 0});
    grid[0][0] = 1;   // 标记已经访问（变成障碍，避免重复入队）

    // 四个方向：下、上、右、左
    int dirs[4][2] = {{1,0}, {-1,0}, {0,1}, {0,-1}};
    int steps = 0;    // 当前已走的步数

    while (!q.empty()) {
        int sz = q.size();   // 当前层的格子数量
        for (int i = 0; i < sz; i++) {
            int x = q.front().first;
            int y = q.front().second;
            q.pop();

            // 到达终点，输出步数
            if (x == n-1 && y == m-1) {
                cout << steps << endl;
                return 0;
            }

            // 尝试四个方向
            for (auto& d : dirs) {
                int nx = x + d[0];
                int ny = y + d[1];
                if (nx >= 0 && nx < n && ny >= 0 && ny < m && grid[nx][ny] == 0) {
                    grid[nx][ny] = 1;   // 标记已访问
                    q.push({nx, ny});
                }
            }
        }
        steps++;   // 每处理完一层步数加 1
    }

    // 队列为空仍未到达终点，输出 -1
    cout << -1 << endl;
    return 0;
}

