#include <iostream>
#include <vector>
#include <queue>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    // 邻接表存储图，节点编号从0到n-1
    vector<vector<int>> adj(n);
    vector<int> indeg(n, 0);

    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        // 转换为0-index
        u--; v--;
        adj[u].push_back(v);
        indeg[v]++;
    }

    // 初始化队列，将所有入度为0的节点加入
    queue<int> q;
    for (int i = 0; i < n; i++) {
        if (indeg[i] == 0) q.push(i);
    }

    vector<int> topo;  // 存储拓扑序列（原始编号+1）
    while (!q.empty()) {
        int u = q.front(); q.pop();
        topo.push_back(u + 1);  // 输出时恢复为1-index
        for (int v : adj[u]) {
            indeg[v]--;
            if (indeg[v] == 0) q.push(v);
        }
    }

    // 如果拓扑序列长度不等于节点总数，说明有环
    if ((int)topo.size() != n) {
        cout << -1 << endl;
    } else {
        for (int i = 0; i < n; i++) {
            cout << topo[i] << (i == n - 1 ? '\n' : ' ');
        }
    }

    return 0;
}

