#include <queue>
#include <climits>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    // 邻接表，存储 (目标节点, 边权)
    vector<vector<pair<int, long long>>> adj(n);
    for (int i = 0; i < m; i++) {
        int u, v;
        long long w;
        cin >> u >> v >> w;
        u--; v--;  // 转换为 0 索引
        adj[u].push_back({v, w});
    }

    const long long INF = 1e18;
    vector<long long> dist(n, INF);
    dist[0] = 0;

    // 小根堆，存储 (当前距离, 节点编号)
    priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<pair<long long, int>>> pq;
    pq.push({0, 0});

    while (!pq.empty()) {
        auto [d, u] = pq.top();
        pq.pop();
        // 如果当前距离大于已知最短距离，跳过
        if (d > dist[u]) continue;

        for (auto [v, w] : adj[u]) {
            long long nd = d + w;
            if (nd < dist[v]) {
                dist[v] = nd;
                pq.push({nd, v});
            }
        }
    }

    // 输出结果
    if (dist[n-1] == INF) {
        cout << -1;
    } else {
        cout << dist[n-1];
    }
    cout << "\n";

    return 0;
}

