#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

typedef long long LL;

// 并查集类
struct DSU {
    vector<int> parent;
    DSU(int n) {
        parent.resize(n);
        for (int i = 0; i < n; i++) parent[i] = i;
    }
    // 查找根节点（带路径压缩）
    int find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }
    // 合并两个集合
    void unite(int a, int b) {
        int ra = find(a);
        int rb = find(b);
        if (ra != rb) parent[ra] = rb;
    }
    // 判断是否连通
    bool same(int a, int b) {
        return find(a) == find(b);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    // 存储边 (权重, u, v)
    vector<pair<int, pair<int, int>>> edges;
    for (int i = 0; i < m; i++) {
        int u, v, w;
        cin >> u >> v >> w;
        // 转为0-index
        u--; v--;
        edges.push_back({w, {u, v}});
    }
    // 按照权重从小到大排序
    sort(edges.begin(), edges.end());

    DSU dsu(n);
    LL total = 0;          // 最小生成树总权值
    int cnt = 0;            // 已经加入的边数

    for (auto& e : edges) {
        int w = e.first;
        int u = e.second.first;
        int v = e.second.second;
        if (!dsu.same(u, v)) {
            dsu.unite(u, v);
            total += w;
            cnt++;
            if (cnt == n - 1) {
                cout << total << '\n';
                return 0;
            }
        }
    }
    // 如果循环结束还没连通，则输出-1
    cout << -1 << '\n';

    return 0;
}

