#include <iostream>
#include <vector>
#include <stack>
using namespace std;

int main() {
    int n, m;
    cin >> n >> m;
    vector<vector<int>> adj(n);
    for (int i = 0; i < m; ++i) {
        int u, v;
        cin >> u >> v;
        --u; --v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    // 颜色数组，-1表示未染色，0和1表示两种颜色
    vector<int> color(n, -1);
    bool isBipartite = true;

    // 遍历每个连通分量
    for (int i = 0; i < n && isBipartite; ++i) {
        if (color[i] != -1) continue;
        // 使用栈模拟DFS递归，栈内存储 (节点, 该节点应染的颜色)
        stack<pair<int, int>> stk;
        stk.push({i, 0});
        while (!stk.empty() && isBipartite) {
            auto p = stk.top(); stk.pop();
            int u = p.first;
            int c = p.second;
            // 如果当前节点已经染色，检查颜色是否与预期一致
            if (color[u] != -1) {
                if (color[u] != c) {
                    isBipartite = false;
                    break;
                }
                continue;
            }
            // 染色当前节点
            color[u] = c;
            // 遍历所有邻居
            for (int v : adj[u]) {
                if (color[v] == -1) {
                    // 未染色则入栈，颜色取反
                    stk.push({v, 1 - c});
                } else if (color[v] == c) {
                    // 相邻节点颜色相同，不是二分图
                    isBipartite = false;
                    break;
                }
            }
        }
    }

    if (isBipartite)
        cout << "YES" << endl;
    else
        cout << "NO" << endl;

    return 0;
}

