bool isPrime(int x) {
    if (x < 2) return false;           // 小于2不是质数
    for (int i = 2; i <= x / i; i++) { // i <= sqrt(x)，防止溢出
        if (x % i == 0) return false;  // 找到因数则不是质数
    }
    return true;
}

