int main() {
    int n;
    cin >> n;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    for (int x : a) {
        vector<int> divisors;
        // 试除法求所有约数
        int i = 1;
        while (i * i <= x) {
            if (x % i == 0) {
                divisors.push_back(i);
                if (i != x / i) {  // 避免重复添加平方根
                    divisors.push_back(x / i);
                }
            }
            ++i;
        }
        // 升序排序
        sort(divisors.begin(), divisors.end());
        // 输出当前数的所有约数
        for (size_t j = 0; j < divisors.size(); ++j) {
            if (j > 0) cout << ' ';
            cout << divisors[j];
        }
        cout << endl;
    }
    return 0;
}

