        for (long long i = 2; i * i <= x; i++) {
            if (x % i == 0) {
                // i 是质因数，更新结果：res = res / i * (i-1)
                res = res / i * (i - 1);
                // 将 x 中的 i 因子全部去除
                while (x % i == 0) {
                    x /= i;
                }
            }
        }
        // 如果最后 x 大于 1，说明还有一个大于 sqrt(原 x) 的质因子
        if (x > 1) {
            res = res / x * (x - 1);
        }
        cout << res << endl;
    }
    return 0;
}

