#include <iostream>
using namespace std;

// 扩展欧几里得算法：求 ax + by = gcd(a,b) 的一组整数解
// 通过引用返回 x, y, g (g = gcd(a,b))
void exgcd(long long a, long long b, long long &x, long long &y, long long &g) {
    if (b == 0) {  // 递归终止条件：b=0时，gcd(a,0)=a，解为 x=1, y=0
        x = 1;
        y = 0;
        g = a;
        return;
    }
    // 递归调用 exgcd(b, a % b)，得到临时解 y, x (注意参数位置交换)
    exgcd(b, a % b, y, x, g);
    // 回溯更新当前层的 y: y -= (a / b) * x
    y -= (a / b) * x;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    while (n--) {
        long long a, b;
        cin >> a >> b;
        long long x, y, g;  // g 用于接收最大公约数，但题目只要求输出 x, y
        exgcd(a, b, x, y, g);
        cout << x << " " << y << "\n";
    }
    return 0;
}

