#include <iostream>
#include <vector>
#include <cstdio>
using namespace std;

// 扩展欧几里得算法，求解 ax + by = gcd(a,b)，返回 gcd 及系数 x, y
void exgcd(__int128 a, __int128 b, __int128 &x, __int128 &y, __int128 &g) {
    if (b == 0) {
        x = 1;
        y = 0;
        g = a;
        return;
    }
    exgcd(b, a % b, y, x, g);
    y -= (a / b) * x;
}

// 输出 __int128 类型的整数（因为 cout 不支持直接输出）
void print(__int128 x) {
    if (x < 0) {
        putchar('-');
        x = -x;
    }
    if (x > 9) print(x / 10);
    putchar((int)(x % 10) + '0');
}

int main() {
    int k;
    cin >> k;
    vector<int> m(k), r(k);
    __int128 M = 1;  // 所有模数的乘积
    for (int i = 0; i < k; ++i) {
        cin >> m[i] >> r[i];
        M *= m[i];
    }
    __int128 ans = 0;
    for (int i = 0; i < k; ++i) {
        __int128 Mi = M / m[i];          // 除当前模数外的乘积
        __int128 ti, y, g;               // ti 是 Mi 模 m[i] 的逆元
        exgcd(Mi, (__int128)m[i], ti, y, g);
        // 将逆元调整到 [0, m[i]) 范围内（g 必为 1，因为模数互质）
        ti = (ti % m[i] + m[i]) % m[i];
        // 累加当前项：ri * Mi * ti
        ans += (__int128)r[i] * Mi * ti;
    }
    ans %= M;  // 取最小非负解
    // 若 ans 为负（一般不会），则加 M 使其为正
    if (ans < 0) ans += M;
    print(ans);
    cout << endl;
    return 0;
}

