#include <iostream>
#include <vector>
#include <cmath>
#include <iomanip>
using namespace std;

int main() {
    int n;
    cin >> n;
    vector<vector<double>> a(n, vector<double>(n + 1));
    for (int i = 0; i < n; ++i)
        for (int j = 0; j <= n; ++j)
            cin >> a[i][j];

    const double eps = 1e-8;

    // 列主元消元
    for (int col = 0; col < n; ++col) {
        // 从当前行到最后一行中找该列绝对值最大的行
        int mx = col;
        for (int i = col + 1; i < n; ++i)
            if (fabs(a[i][col]) > fabs(a[mx][col]))
                mx = i;
        // 如果最大绝对值几乎为零，跳过该列（该列对应的变量视为自由变量）
        if (fabs(a[mx][col]) < eps)
            continue;
        // 交换到当前行
        swap(a[col], a[mx]);
        // 消去下面所有行该列的元素
        for (int i = col + 1; i < n; ++i) {
            double t = a[i][col] / a[col][col];
            for (int j = col; j <= n; ++j)
                a[i][j] -= t * a[col][j];
        }
    }

    // 回代
    vector<double> res(n, 0.0);
    bool infinite = false;
    for (int i = n - 1; i >= 0; --i) {
        if (fabs(a[i][i]) < eps) {
            // 主元为零，检查常数项
            if (fabs(a[i][n]) > eps) {
                cout << "No solution" << endl;
                return 0;
            } else {
                infinite = true;
                continue; // 自由变量，不赋值
            }
        }
        double s = a[i][n];
        for (int j = i + 1; j < n; ++j)
            s -= a[i][j] * res[j];
        res[i] = s / a[i][i];
    }

    if (infinite) {
        cout << "Infinite solutions" << endl;
        return 0;
    }

    cout << fixed << setprecision(2);
    for (int i = 0; i < n; ++i)
        cout << "x" << i + 1 << "=" << res[i] << endl;

    return 0;
}

