using namespace std;

int main() {
    int n, m;
    cin >> n >> m;
    vector<int> p(m);
    for (int i = 0; i < m; ++i) {
        cin >> p[i];
    }

    long long ans = 0;
    // 枚举所有非空子集，用二进制表示
    for (int mask = 1; mask < (1 << m); ++mask) {
        long long mul = 1;  // 当前子集中质数的乘积
        int bits = 0;       // 当前子集中质数的个数
        bool overflow = false;
        for (int i = 0; i < m; ++i) {
            if (mask >> i & 1) {
                mul *= p[i];
                bits++;
                if (mul > n) {  // 乘积超过n，提前退出，后续乘法只会更大
                    overflow = true;
                    break;
                }
            }
        }
        if (overflow) continue;  // 乘积超过n，不参与容斥
        // 容斥原理：奇数个元素加，偶数个元素减
        if (bits & 1) {
            ans += n / mul;
        } else {
            ans -= n / mul;
        }
    }
    cout << ans << endl;
    return 0;
}

