int main() {
    int n;
    cin >> n;
    vector<int> a(n + 1); // 1-based 存储每堆重量
    for (int i = 1; i <= n; ++i) cin >> a[i];

    // 计算前缀和，s[i] 表示前 i 堆的总重量
    vector<long long> s(n + 1, 0);
    for (int i = 1; i <= n; ++i) s[i] = s[i - 1] + a[i];

    // dp[l][r] 表示合并区间 [l, r] 的最小代价
    vector<vector<long long>> dp(n + 1, vector<long long>(n + 1, 0));

    // 区间长度从 2 到 n
    for (int len = 2; len <= n; ++len) {
        for (int l = 1; l + len - 1 <= n; ++l) { // 左端点
            int r = l + len - 1;                 // 右端点
            dp[l][r] = 1e18;                     // 初始化为一个很大的数
            // 枚举分割点 k，将区间分为 [l, k] 和 [k+1, r]
            for (int k = l; k < r; ++k) {
                long long cost = dp[l][k] + dp[k + 1][r] + (s[r] - s[l - 1]);
                if (cost < dp[l][r]) dp[l][r] = cost;
            }
        }
    }

    cout << dp[1][n] << endl; // 输出合并全部石子堆的最小代价
    return 0;
}

