// 计算 1 到 n 中数码 x 出现的次数
long long count(int n, int x) {
    if (n < 0) return 0;
    long long res = 0;
    long long i = 1;
    while (i <= n) {
        long long high = n / (i * 10);   // 当前位的高位部分
        int cur = (n / i) % 10;          // 当前位的数字
        long long low = n % i;           // 当前位的低位部分
        if (x != 0) {
            // x 非 0 的情况，统计高位贡献
            res += high * i;
            if (cur > x) res += i;
            else if (cur == x) res += low + 1;
        } else {
            // x == 0 的情况，高位不能为 0，需要特殊处理
            if (high > 0) {
                res += (high - 1) * i;   // 高位从 1 到 high-1 时，低位任意
                if (cur > 0) res += i;    // 高位等于 high 且当前位 > 0
                else if (cur == 0) res += low + 1; // 当前位等于 0
            }
        }
        i *= 10;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int a, b;
    while (cin >> a >> b) {
        if (a == 0 && b == 0) break;
        if (a > b) swap(a, b);
        for (int i = 0; i < 10; i++) {
            long long cnt = count(b, i) - count(a - 1, i);
            cout << cnt;
            if (i < 9) cout << ' ';
        }
        cout << '\n';
    }
    return 0;
}

