#include <iostream>
#include <vector>
#include <climits>
using namespace std;

int main() {
    int n;
    cin >> n;
    // 读入邻接矩阵，a[i][j] 表示从 i 到 j 的边权（距离）
    vector<vector<int>> a(n, vector<int>(n));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            cin >> a[i][j];
        }
    }

    const int INF = INT_MAX / 2;  // 防止加法溢出
    int total = 1 << n;            // 状态总数
    // dp[mask][j]：当前访问过的点集为 mask，且最后停留在 j 的最短路径长度
    vector<vector<int>> dp(total, vector<int>(n, INF));
    dp[1][0] = 0;  // 初始状态：只访问了起点 0，最后在 0 的距离为 0

    // 枚举所有状态 mask
    for (int mask = 1; mask < total; ++mask) {
        // 枚举当前最后到达的点 j（必须已在 mask 中）
        for (int j = 0; j < n; ++j) {
            if (!(mask >> j & 1)) continue;  // j 不在 mask 中则跳过
            // 枚举前一个点 k（必须也在 mask 中，且 k != j）
            // 实际上 mask^(1<<j) 表示去掉 j 后的点集
            int pre_mask = mask ^ (1 << j);
            for (int k = 0; k < n; ++k) {
                if (!(pre_mask >> k & 1)) continue;  // k 不在前一个点集中
                // 从状态 (pre_mask, k) 转移而来，加上边 k->j
                dp[mask][j] = min(dp[mask][j], dp[pre_mask][k] + a[k][j]);
            }
        }
    }

    // 最终要求遍历所有点且回到起点 0，即 mask = (1<<n)-1，且最后在 0
    cout << dp[(1 << n) - 1][0] << endl;

    return 0;
}

