#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

const int MAXN = 6005;
int n;
int w[MAXN];                 // 每个节点的快乐指数
vector<int> adj[MAXN];       // 邻接表，存储子节点
bool has_fa[MAXN];           // 标记节点是否有父节点
int dp0[MAXN], dp1[MAXN];    // dp0[u] 不选u，dp1[u] 选u 时子树的最大值

void dfs(int u) {
    dp1[u] = w[u];           // 选u时，初始快乐指数为自身
    dp0[u] = 0;
    for (int v : adj[u]) {
        dfs(v);              // 递归处理子节点
        // 不选u：子节点可选可不选，取最大值
        dp0[u] += max(dp0[v], dp1[v]);
        // 选u：子节点只能不选
        dp1[u] += dp0[v];
    }
}

int main() {
    cin >> n;
    for (int i = 1; i <= n; ++i)
        cin >> w[i];
    // 读入n-1条边，k是l的上司（父节点）
    for (int i = 1; i < n; ++i) {
        int l, k;
        cin >> l >> k;
        adj[k].push_back(l);  // k是父节点，l是子节点
        has_fa[l] = true;
    }
    // 找到根节点（没有父节点的节点）
    int root = 1;
    for (int i = 1; i <= n; ++i) {
        if (!has_fa[i]) {
            root = i;
            break;
        }
    }
    dfs(root);
    // 输出根节点选或不选的最大值
    cout << max(dp0[root], dp1[root]) << endl;
    return 0;
}

