    dirs = [(1,0),(-1,0),(0,1),(0,-1)]
    def dfs(x,y):
        if f[x][y]: return f[x][y]
        f[x][y]=1
        for dx,dy in dirs:
            nx,ny = x+dx,y+dy
            if 0<=nx<n and 0<=ny<m and h[nx][ny]<h[x][y]:
                f[x][y] = max(f[x][y], dfs(nx,ny)+1)
        return f[x][y]
    ans = 0
    for i in range(n):
        for j in range(m):
            ans = max(ans, dfs(i,j))
    print(ans)

