#include <iostream>
#include <algorithm> // for max
using namespace std;

const int MAXN = 305;
int n, m;
int h[MAXN][MAXN];   // 存储高度
int f[MAXN][MAXN];   // 记忆化数组，f[i][j] 表示从 (i,j) 出发的最长路径长度（格子数）

// 方向数组：上、下、左、右
int dx[4] = {-1, 1, 0, 0};
int dy[4] = {0, 0, -1, 1};

// DFS 记忆化搜索
int dfs(int x, int y) {
    if (f[x][y] != 0) return f[x][y]; // 已计算过，直接返回
    f[x][y] = 1; // 初始化长度为1（只含自身格子）
    for (int d = 0; d < 4; ++d) {
        int nx = x + dx[d], ny = y + dy[d];
        // 检查边界且高度严格递减
        if (nx >= 0 && nx < n && ny >= 0 && ny < m && h[nx][ny] < h[x][y]) {
            f[x][y] = max(f[x][y], dfs(nx, ny) + 1);
        }
    }
    return f[x][y];
}

int main() {
    cin >> n >> m;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            cin >> h[i][j];
        }
    }
    int ans = 0;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            ans = max(ans, dfs(i, j)); // 取所有起点的最大值
        }
    }
    cout << ans << endl;
    return 0;
}

