#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    int n;
    cin >> n;
    vector<pair<int, int>> intervals(n);
    for (int i = 0; i < n; i++) {
        cin >> intervals[i].first >> intervals[i].second;
    }
    // 按区间右端点从小到大排序
    sort(intervals.begin(), intervals.end(), [](const pair<int, int>& a, const pair<int, int>& b) {
        return a.second < b.second;
    });
    int cnt = 0;          // 记录选点数
    int last = 0;         // 上一个选点的位置（注意：与Python保持一致初始为0）
    for (const auto& it : intervals) {
        int l = it.first, r = it.second;
        // 如果当前区间左端点 > 上一个选点位置，则必须选一个新点（选在当前区间右端点）
        if (l > last) {
            cnt++;
            last = r;
        }
    }
    cout << cnt << endl;
    return 0;
}

