#include <iostream>
#include <cmath>
#include <string>
using namespace std;

int main() {
    int t;
    cin >> t;
    // 处理 t 个测试用例
    while (t--) {
        int n;
        string comp;
        cin >> n >> comp;  // 读入 n 和复杂度字符串
        if (comp == "O(n)") {
            // O(n) 算法每秒能执行 1e7 次，n 必须 ≤ 1e7
            cout << (n <= 10000000 ? "YES" : "NO") << endl;
        } else if (comp == "O(nlogn)") {
            // 计算 n * log2(n)，用 double 防止溢出，与 1e7 比较
            double val = n * log2(n);
            cout << (val <= 10000000 ? "YES" : "NO") << endl;
        } else if (comp == "O(n²)") {
            // 注意字符串中的 '²' 是特殊字符，但这里直接匹配原始输入
            // O(n²) 算法 n^2 ≤ 10000000 即可
            long long nn = (long long)n * n;
            cout << (nn <= 10000000 ? "YES" : "NO") << endl;
        } else if (comp == "O(logn)") {
            // O(log n) 始终可行
            cout << "YES" << endl;
        }
    }
    return 0;
}

